import {fitSummary,officialSizingMarkup} from './fit-display.mjs';
import products from './catalog.mjs';
import {lengthRecommendation,sizingSource,heightChart} from './sizing.mjs';
import {genderLabels,matchingSizes,filterProducts,sortProducts,groupProducts,safeIds,displayImageUrl,imageCandidates} from './core.mjs';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('atlas:'+key))??fallback;}catch{return fallback;}};
const write=(key,value)=>{try{localStorage.setItem('atlas:'+key,JSON.stringify(value));}catch{toast('浏览器不允许保存；当前页面仍可使用，离开前可导出收藏。');}};
let saved=safeIds(read('saved',[]),products),compared=safeIds(read('compare',[]),products).slice(0,4),limit=18;
let groups=[],editions=new Map(),views=new Map(),toastTimer;
const modal=$('modal');let lastFocus;
function toast(text){$('toast').textContent=text;$('toast').style.opacity='1';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.opacity='0',3000);}
function openModal(title,html){lastFocus=document.activeElement;$('modal-title').textContent=title;$('modal-content').innerHTML=html;if(!modal.open){if(modal.showModal)modal.showModal();else modal.setAttribute('open','');}modal.scrollTop=0;}
function closeModal(){if(modal.close)modal.close();else modal.removeAttribute('open');lastFocus?.focus();}
$('close-modal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
const brands=[...new Set(products.map(p=>p.brand))].sort();
brands.forEach(b=>$('brand').add(new Option(b,b)));
$('currency').innerHTML='<option value="">全部币种</option>';
[...new Set(products.flatMap(p=>p.price?[p.price.currency]:[]))].sort().forEach(c=>$('currency').add(new Option(c,c)));
const failedImages=new Set();
[...new Set(products.map(p=>p.season))].sort((a,b)=>a==='待核实'?1:b==='待核实'?-1:b.localeCompare(a)).forEach(s=>$('season').add(new Option(s,s)));
for(let i=1;i<=10;i++){ $('flex-min').add(new Option(String(i),String(i)));$('flex-max').add(new Option(String(i),String(i))); }
const officialCount=products.filter(p=>p.flex.kind==='official').length,fitCount=products.filter(p=>p.fit.length).length;
$('coverage').textContent=`${brands.length} 个品牌 · ${products.length} 条型号记录 · ${officialCount} 条官方数值硬度 · ${fitCount} 款已收录官方体重数据`;
$('catalog-number').textContent='真实产品 / 开放探索';
function filters(){return {search:$('search').value,brand:$('brand').value,shape:$('shape').value,min:$('flex-min').value,max:$('flex-max').value,official:$('official-only').checked,level:$('level').value,terrain:$('terrain').value,gender:$('gender').value,riderGender:$('rider-gender').value,season:$('season').value,length:$('length').value,currency:$('currency').value,budget:$('budget').value,saved:$('only-saved').checked,weight:$('weight').value,height:$('height').value,sizingMode:$('sizing-mode').value,fit:$('fit-only').checked};}
function saveURL(f){const q=new URLSearchParams();for(const [k,v] of Object.entries({...f,sort:$('sort').value}))if(v!==''&&v!==false&&v!=='all'&&v!=='curated')q.set(k,String(v));try{history.replaceState(null,'',location.pathname+(q.size?'?'+q.toString():'')+'#catalog');}catch{}}
const urlKeys={search:'search',brand:'brand',shape:'shape',min:'flex-min',max:'flex-max',level:'level',terrain:'terrain',gender:'gender',riderGender:'rider-gender',season:'season',length:'length',currency:'currency',budget:'budget',weight:'weight',height:'height',sizingMode:'sizing-mode',sort:'sort'};
const initial=new URLSearchParams(location.search);for(const [k,id] of Object.entries(urlKeys))if(initial.has(k))$(id).value=initial.get(k);
if(initial.get('height')||initial.get('weight'))document.querySelector('.fit-panel').open=true;
for(const [k,id] of [['official','official-only'],['saved','only-saved'],['fit','fit-only']])$(id).checked=initial.get(k)==='true';
function priceText(p){if(!p.price)return '定价待核实';const x=p.price;return `${x.currency} ${new Intl.NumberFormat('en-US',{maximumFractionDigits:x.currency==='JPY'?0:2,minimumFractionDigits:x.currency==='JPY'?0:2}).format(x.amount)}${x.maxAmount>x.amount||x.startsAt?' 起':''}`;}
function flexText(p){return p.flex.value===null?'硬度待核实':`${p.flex.value}/10 · ${p.flex.kind==='official'?'官方数值':'文字换算 ≈'}`;}
function recommendation(p){return lengthRecommendation(p,{weight:$('weight').value,height:$('height').value,general:$('sizing-mode').value!=='official'});}
function sizesText(p){const r=recommendation(p);if(r.kind==='official'){if(r.reason==='match')return '厂商体重表：'+r.sizes.join(' / ')+' cm'+(r.upperOnly.length?' · '+r.upperOnly.join(' / ')+' 仅上限参考':'');if(r.reason==='source-conflict')return '已核实范围无匹配 · 部分官方数据冲突待核';if(r.reason==='outside-weight-range')return '当前体重不在已核实范围内';return '填写体重查看厂商建议 · 可选 '+p.sizes.join(' / ')+' cm';}if(r.kind==='estimate')return '通用估算 ≈ '+r.range.join('–')+' cm · '+(r.sizes.length?'此款可选 '+r.sizes.join(' / ')+' cm':'此款已知长度无匹配');if(r.reason==='special-design')return '儿童 / 特殊设计：不套通用估算，请核对型号建议';if(r.reason==='height-outside-chart')return '缺少厂商体重表 · 身高超出通用表152–183cm';return '可选 '+(p.sizes.length?p.sizes.join(' / ')+' cm':'长度待核实')+($('sizing-mode').value==='official'?' · 厂商体重表待核':' · 填写身高可查看通用参考');}

function current(group){return group.editions.find(p=>p.id===editions.get(group.key))||group.editions[0];}
function imageMarkup(p,cls=''){const selected=views.get(p.id)||0;const candidates=imageCandidates(p.images,selected).filter(x=>!failedImages.has(x.url));if(!p.images.length)return '<div class="img-error">板花待核实<br>可前往官网查看</div>';const first=candidates[0];if(!first)return imageUnavailable(p);return '<img class="'+esc(cls)+'" src="'+esc(first.url)+'" alt="'+esc(p.brand+' '+p.model+' '+p.season+' '+p.images[first.index].label)+'" data-image-product="'+esc(p.id)+'" data-image-index="'+first.index+'" loading="lazy" decoding="async" referrerpolicy="no-referrer">';}
function imageUnavailable(p){return '<div class="img-error" role="status">官方图片暂不可用<br><a href="'+esc(p.source)+'" target="_blank" rel="noopener noreferrer">前往官网查看 ↗</a><br><button type="button" data-image-retry="'+esc(p.id)+'">重试图片</button></div>';}

function card(group,n){const p=current(group),img=views.get(p.id)||0;const rec=recommendation(p),match=rec.sizes;return `<article class="card" data-id="${esc(p.id)}" data-group="${n}"><div class="image-area" aria-label="${esc(p.model)} 官方视图">${imageMarkup(p)}<span class="badge">${esc(p.season)} · ${p.status==='reviewed'?'板型 / 硬度已核':'部分规格待核'}</span><button class="fav" data-action="save" aria-label="${saved.includes(p.id)?'取消收藏':'收藏'} ${esc(p.model)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button>${p.images.length>1?`<button class="img-arrow prev" data-action="image-prev" aria-label="上一张板花">‹</button><button class="img-arrow next" data-action="image-next" aria-label="下一张板花">›</button>`:''}<div class="img-caption"><span>${esc(p.images[img]?.label||'图源待核实')}</span><span>${p.images.length?(img+1)+' / '+p.images.length:'待补图'}</span></div></div><div class="card-body"><div class="brand-line"><span>${esc(p.brand)}</span><span>${esc(genderLabels[p.gender]||'定位待核')}</span></div><h3>${esc(p.model)}</h3><div class="chip-row"><span class="chip">${esc(p.shape||p.shapeOriginal||'板型待核实')}</span>${p.terrains.slice(0,2).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div><div class="flex-line"><span>FLEX / 硬度</span><b>${esc(flexText(p))}</b></div><div class="flex-meter ${p.flex.kind}" aria-hidden="true">${Array.from({length:10},(_,i)=>`<i class="${p.flex.value!==null&&i<p.flex.value?'on':''}"></i>`).join('')}</div><div class="price">${esc(priceText(p))}</div><div class="price-context">${p.price?`${p.price.region} · ${esc(p.price.season)} · 官网${p.price.kind==='msrp'?' MSRP':p.price.kind==='official-display'?'展示价':'常规定价'}<br>${p.price.kind==='msrp'?'':'MSRP 名称未单独确认；非实时成交价'}`:'币种 / 地区未固定 · MSRP 待核实'}</div><div class="size-note ${match.length?(rec.kind==='estimate'?'fit-estimate':'fit-match'):''}">${esc(sizesText(p))}</div>${p.fit.length||p.heightGuide?`<button class="fit-table-btn" data-action="fit-table">${esc(fitSummary(p))} ↗</button>`:'<div class="fit-pending">型号体重表待核实</div>'}<div class="edition-nav"><button data-action="season-prev" aria-label="上一雪季" ${group.editions.length<2?'disabled':''}>←</button><span>${p.season==='待核实'?'雪季待核实 · 官网当前条目':esc(p.season)+(group.editions.length>1?' · '+group.editions.length+' 个雪季':' · 已收录 1 季')}</span><button data-action="season-next" aria-label="下一雪季" ${group.editions.length<2?'disabled':''}>→</button></div><div class="card-actions"><button data-action="compare" aria-pressed="${compared.includes(p.id)}">${compared.includes(p.id)?'✓ 已加入':'＋ 加入对比'}</button><button class="detail-btn" data-action="detail">规格与来源 ↗</button></div></div></article>`;}
function bindImageErrors(){document.querySelectorAll('img[data-image-product]').forEach(img=>{if(img.dataset.bound)return;img.dataset.bound='true';const p=products.find(p=>p.id===img.dataset.imageProduct);let queue=imageCandidates(p.images,views.get(p.id)||0).filter(x=>!failedImages.has(x.url));let active=queue.find(x=>x.url===img.getAttribute('src'))||queue[0];const success=()=>{if(!active)return;views.set(p.id,active.index);img.dataset.imageIndex=active.index;img.alt=p.brand+' '+p.model+' '+p.season+' '+p.images[active.index].label;const caption=img.closest('.image-area')?.querySelector('.img-caption');if(caption){caption.children[0].textContent=p.images[active.index].label;caption.children[1].textContent=(active.index+1)+' / '+p.images.length;}};const failure=()=>{if(!img.isConnected)return;failedImages.add(img.getAttribute('src'));queue=queue.filter(x=>!failedImages.has(x.url));active=queue[0];if(active){img.src=active.url;return;}img.onerror=null;img.insertAdjacentHTML('afterend',imageUnavailable(p));img.remove();};img.onload=success;img.onerror=failure;if(img.complete){if(img.naturalWidth)success();else failure();}});}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-image-retry]');if(!btn)return;const p=products.find(x=>x.id===btn.dataset.imageRetry);imageCandidates(p.images).forEach(x=>failedImages.delete(x.url));const container=btn.closest('.img-error');container.outerHTML=imageMarkup(p);bindImageErrors();});

function render(updateURL=true){const f=filters();$('budget').disabled=!f.currency;if(!f.currency)$('budget').value='';
 const filtered=sortProducts(filterProducts(products,f,saved),$('sort').value,f.currency);groups=groupProducts(filtered);
 $('result-count').textContent=`${groups.length} 个系列 / ${filtered.length} 条型号 / 雪季记录`;
 $('active-summary').textContent=f.saved?'仅显示本浏览器收藏':'按官网资料筛选 · 未核实字段明确留白';
 let notice='';if(f.min!==''&&f.max!==''&&+f.min>+f.max)notice='最低硬度大于最高硬度，请调整筛选。';
 else if($('sort').value.startsWith('price')&&!f.currency)notice='请先在筛选中选择同一种定价币种，再按价格排序；不同币种不直接比较。';
 else if(f.fit&&!f.weight&&(!f.height||f.sizingMode==='official'))notice='请填写体重；缺表通用估算需填写152–183cm范围内的身高。';
 $('notice').hidden=!notice;$('notice').textContent=notice;
 $('grid').innerHTML=groups.length?groups.slice(0,limit).map(card).join(''):'<div class="empty"><h3>这次还没有合适的匹配</h3><p>试着放宽品牌、硬度或长度条件。未知规格不会被视作已匹配。</p><button data-reset>清空筛选</button></div>';
 $('load-more').hidden=limit>=groups.length;$('saved-count').textContent=saved.length;updateDock();bindImageErrors();if(updateURL)saveURL(f);
}
function updateDock(){$('compare-dock').hidden=!compared.length;$('compare-count').textContent=`已选 ${compared.length} 款雪板`;$('open-compare').disabled=compared.length<2;}
function toggleSaved(id){if(saved.includes(id))saved=saved.filter(x=>x!==id);else saved.push(id);write('saved',saved);render(false);}
function toggleCompare(id){if(compared.includes(id))compared=compared.filter(x=>x!==id);else if(compared.length<4)compared.push(id);else return toast('最多对比 4 款，请先移除一款。');write('compare',compared);render(false);}
$('grid').addEventListener('click',e=>{if(e.target.closest('[data-reset]'))return reset();const btn=e.target.closest('[data-action]'),el=btn?.closest('.card');if(!el)return;const p=products.find(x=>x.id===el.dataset.id),g=groups[Number(el.dataset.group)];const action=btn.dataset.action;if(action==='save')toggleSaved(p.id);if(action==='compare')toggleCompare(p.id);if(action==='detail'||action==='fit-table')showDetail(p,action==='fit-table');if(action.startsWith('image-')){views.set(p.id,((views.get(p.id)||0)+(action==='image-next'?1:-1)+p.images.length)%p.images.length);render(false);}if(action.startsWith('season-')){const idx=g.editions.indexOf(p);editions.set(g.key,g.editions[(idx+(action==='season-next'?1:-1)+g.editions.length)%g.editions.length].id);render(false);}});
let touchX=null;$('grid').addEventListener('touchstart',e=>{if(e.target.closest('.image-area'))touchX=e.changedTouches[0].clientX;},{passive:true});$('grid').addEventListener('touchend',e=>{const area=e.target.closest('.image-area');if(area&&touchX!==null){const d=e.changedTouches[0].clientX-touchX;if(Math.abs(d)>50)area.querySelector(d<0?'.next':'.prev')?.click();}touchX=null;},{passive:true});
function showDetail(p,focusSizing=false){const fields=[['板型',p.shape||p.shapeOriginal||'待核实'],['厂商系列定位',genderLabels[p.gender]||'待核实'],['男女适用',genderLabels[p.riderGender??p.gender]||'未标注男女（两边均显示）'],['统一显示硬度',flexText(p)],['厂商原始硬度',p.flex.original||'未取得官方数值'],['雪季',p.season+' · '+p.seasonEvidence],['水平提示（编辑归类）',p.levels.join(' / ')||'未归类'],['玩法提示（编辑归类）',p.terrains.join(' / ')||'未归类'],['官网 MSRP / 定价',priceText(p)],['价格口径',p.price?`${p.price.region} · ${p.price.tax} · ${p.price.kind==='msrp'?'明确 MSRP':p.price.kind==='official-display'?'官网展示售价，MSRP / 常规价待核实':'官网常规定价，未明确标为 MSRP'}`:p.priceNote||'待核实'],['可选长度',p.sizes.join(' / ')+' cm'],['长度建议',sizesText(p)],['核查日期',p.checkedAt]];
 openModal(`${p.brand} · ${p.model}`,`<div class="detail-layout"><div class="detail-visual">${imageMarkup(p)}</div><div class="detail-specs">${fields.map(([k,v])=>`<div class="spec"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div></div><div class="explanation"><p>${esc(p.shapeNote||'')}</p><p>${esc(p.flex.method||'官方 1–10 是品牌内相对尺度，保留数值不代表不同品牌已经完成物理标定。')}</p><p>${esc(p.recommendationBasis)}</p>${p.notes.map(n=>`<p>${esc(n)}</p>`).join('')}${p.flex.source?`<p><a href="${esc(p.flex.source)}" target="_blank" rel="noopener noreferrer">核对硬度原文 ↗</a></p>`:''}<h3 id="detail-sizing" tabindex="-1">官方尺码依据</h3>${officialSizingMarkup(p)}${p.fit.length?'':`<p>此款尚无已核实的型号体重表。通用估算仅筛选已知板长，不是厂商适配结论，也不判断雪鞋与板宽。</p>${generalSizingInfo()}`}<a class="source-link" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">打开品牌官网产品来源 ↗</a>${p.price?` · <a class="source-link" href="${esc(p.price.source)}" target="_blank" rel="noopener noreferrer">核对 ${esc(p.price.region)} / ${esc(p.price.currency)} 定价来源 ↗</a>`:""}<h3>图片来源</h3>${p.images.map((img,i)=>`<p>${i+1}. ${esc(img.season)} · ${esc(img.label)} · © ${esc(img.credit)} · <a href="${esc(img.url)}" target="_blank" rel="noopener noreferrer">原图</a> / <a href="${esc(img.source)}" target="_blank" rel="noopener noreferrer">来源页面</a></p>`).join('')}<p>图片来自所标注的官方产品页面；不同尺寸、底板配色或实物可能不同。图片与商标权利属于品牌，项目没有取得独立转载授权。</p></div>`);bindImageErrors();if(focusSizing){$('detail-sizing').scrollIntoView({block:'start'});$('detail-sizing').focus({preventScroll:true});}}
function showCompare(){const ps=compared.map(id=>products.find(p=>p.id===id));if(ps.length<2)return toast('至少加入 2 款再对比。');const currencies=new Set(ps.map(p=>p.price?.currency).filter(Boolean));const rows=[['雪季',p=>p.season],['板型',p=>p.shape||p.shapeOriginal||'待核实'],['统一显示硬度',flexText],['原始硬度',p=>p.flex.original||'待核实'],['厂商系列定位',p=>genderLabels[p.gender]||'待核实'],['水平（编辑归类）',p=>p.levels.join(' / ')||'待核实'],['玩法（编辑归类）',p=>p.terrains.join(' / ')||'待核实'],['官网价 / MSRP',priceText],['价格口径',p=>p.price?`${p.price.region} · ${p.price.season} · 官网${p.price.kind==='msrp'?'MSRP':p.price.kind==='official-display'?'展示价；MSRP 未明确':'常规定价；MSRP 未明确'}`:'待核实'],['长度 cm',p=>p.sizes.join(' / ')],['长度建议（注明依据）',sizesText],['核查日期',p=>p.checkedAt]];openModal('把候选板放在一起',`${currencies.size>1?'<p class="notice">含不同币种与地区，只并列展示原价；不做汇率换算或价格高低排名。</p>':''}<div class="compare-scroll" tabindex="0" aria-label="横向滚动查看对比表"><table class="compare-table"><thead><tr><th>对比项目</th>${ps.map(p=>`<th>${imageMarkup(p)}<button class="table-link" data-detail-id="${esc(p.id)}">${esc(p.brand+' '+p.model)}</button></th>`).join('')}</tr></thead><tbody>${rows.map(([k,fn])=>`<tr><th>${esc(k)}</th>${ps.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th>官方来源</th>${ps.map(p=>`<td><a class="source-link" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">产品页面 ↗</a></td>`).join('')}</tr></tbody></table></div><p class="explanation">官方硬度仍是品牌内相对尺度；文字换算为编辑估值。不同雪季或不同长度的脚感可能不同。</p>`);bindImageErrors();}
$('modal-content').addEventListener('click',e=>{const b=e.target.closest('[data-detail-id]');if(b)showDetail(products.find(p=>p.id===b.dataset.detailId));});
function generalSizingInfo(){return '<div class="generic-guide"><h3>缺表时的通用参考 ≈</h3><p>来源为 RIDE 官方成人选板指南，不是本型号的厂家尺码表。仅在缺少型号体重表时启用；有表但体重不匹配时不会用估算覆盖。中间身高为编辑线性插值，未填写体重时使用三档体重范围的并集。儿童、特殊设计和152–183cm之外不自动估算。</p><table class="source-table"><thead><tr><th>身高cm</th><th>&lt;59kg</th><th>59–82kg</th><th>&gt;82kg</th></tr></thead><tbody>'+heightChart.map(r=>'<tr><td>'+r.height+'</td>'+r.ranges.map(x=>'<td>'+x.join('–')+'</td>').join('')+'</tr>').join('')+'</tbody></table><a href="'+sizingSource+'" target="_blank" rel="noopener noreferrer">RIDE官方通用指南 ↗</a><p>CASI资料强调体重、用途和厂商范围；这里未把身高表冒称CASI标准。</p></div>';}
function showAbout(){const rows=brands.map(b=>{const ps=products.filter(p=>p.brand===b);return `<tr><td>${esc(b)}</td><td>${ps.length}</td><td>${ps.filter(p=>p.shape).length}</td><td>${ps.filter(p=>p.flex.kind==='official').length}</td><td>${ps.filter(p=>p.fit.length).length}</td><td>${[...new Set(ps.map(p=>p.season))].join(' / ')}</td></tr>`;}).join('');openModal('数据有出处，缺口也公开',`<div class="explanation"><p>核查日期：2026-10-28。当前为官网目录快照，不是各品牌历年全产品档案；完整覆盖仍需逐品牌、逐雪季复核。收录型号不等于每一个字段都已确认。部分官网当前页面未明确雪季，以“待核实”显示，不用抓取年份代替产品雪季。</p><div class="compare-scroll"><table class="source-table"><thead><tr><th>品牌</th><th>记录数</th><th>已核板型</th><th>官方硬度</th><th>体重表</th><th>雪季</th></tr></thead><tbody>${rows}</tbody></table></div><h3>1 — 官方数值与换算估值</h3><p>官方已有 1–10 评分时，原样展示。文字描述通常按 soft/softer=3、mid-soft=4、medium=5、mid-stiff=7、stiff=8 映射；Burton Personality、RIDE Response等按逐款说明换算，标为“文字换算 ≈”，误差约 ±1；没有依据就留空。这个方法用于浏览导航，不是材料测试或跨品牌标定。YONEX 原生 F/T 与 SW 详见产品说明，未建立映射时不强制变成 1–10。</p><h3>2 — MSRP 与地区</h3><p>产品数据标出币种、地区、雪季、核查日。当前从官方产品目录取得的是常规定价或官方原价；只有明确写为 MSRP 的证据才标 MSRP，没有明确名称就显示“MSRP 未单独确认”。Nitro 已核实国际站 EUR 展示售价，适用国家、税费及是否MSRP仍待核实。价格非实时，不含跨区税费换算；筛选预算前先选币种。</p><h3>3 — 板型、水平与体型</h3><p>板型依据官网标签或正文，不由板花猜测。Asym / Hybrid 等原生板型保留说明；没有足够依据映射三分类时，继续标待核实。水平、玩法由编辑按官方文案关键词归类；缺少依据不自动归类。有厂商表时优先按体重；只有缺表时才按RIDE成人通用身高/体重指南给出参考范围。中间身高采用编辑线性插值，152–183cm之外不外推，儿童和已识别的特殊设计不套表。男女筛选不改变长度公式。</p>${generalSizingInfo()}<h3>4 — 板花与雪季</h3><p>卡片图片左右按钮 / 手指横滑切换同雪季官方视图；卡片底部箭头切换已收录的同型号雪季。只有 1 季时按钮禁用，不制造往年板花。图片均保留官方图源和品牌署名；缩略图失败会重试原图与其它已收录官方视图；全部失败提供官网入口和手动重试。缺少可靠图源时明确待补图，不猜图片地址。不同尺码可能使用不同配色。</p><h3>5 — 隐私与分享</h3><p>无需登录。收藏、对比只存在本浏览器；可导出 JSON 后在另一设备导入。筛选条件会写入地址栏，复制网址即可分享相同筛选。没有广告、统计或后台数据库。</p><h3>6 — 维护边界</h3><p>目录只包含此次公开接口返回并通过型号规则筛选的记录；品牌未公开、分页外、历史或地区专供型号可能缺失。项目 README 包含品牌导入、schema 校验、图片授权与 GitHub Pages 发布步骤。</p></div>`);}
for(const id of ['about-nav','coverage-btn','method-btn'])$(id).onclick=showAbout;
$('saved-nav').onclick=()=>{$('only-saved').checked=!$('only-saved').checked;limit=18;render();$('catalog').scrollIntoView({behavior:'smooth'});};
$('open-compare').onclick=showCompare;$('clear-compare').onclick=()=>{compared=[];write('compare',compared);render(false);};
function reset(){ $('filters-form').reset();$('weight').value='';$('height').value='';$('boot').value='';$('fit-only').checked=false;$('sizing-mode').value='auto';$('rider-gender').value='';$('sort').value='curated';limit=18;render();}
$('reset').onclick=reset;$('filters-form').onsubmit=e=>e.preventDefault();
$('filter-toggle').onclick=()=>{const expanded=document.querySelector('.filters').classList.toggle('expanded');$('filter-toggle').setAttribute('aria-expanded',String(expanded));$('filter-toggle').textContent=expanded?'收起筛选 −':'展开筛选 ＋';};
document.querySelectorAll('#filters-form input,#filters-form select,#sort,#sizing-mode,#rider-gender,#weight,#height,#boot,#fit-only').forEach(el=>el.addEventListener(el.tagName==='INPUT'&&el.type!=='checkbox'?'input':'change',()=>{limit=18;render();}));
$('load-more').onclick=()=>{limit+=18;render(false);};
$('export-saved').onclick=()=>{const b=new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),saved},null,2)],{type:'application/json'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='board-atlas-favorites.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import-saved').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error();const data=JSON.parse(await file.text());if(data.schemaVersion!==1||!Array.isArray(data.saved))throw Error();const valid=safeIds(data.saved,products);saved=[...new Set([...saved,...valid])];write('saved',saved);render(false);toast(`已合并 ${valid.length} 条有效收藏`);}catch{toast('无法读取收藏文件，请选择本工具导出的 JSON。');}e.target.value='';};
const heroIds=['capita-capita-paradise-womens-snowboard-2027','capita-capita-space-metal-fantasy-womens-snowboard-2027'];$('hero-boards').innerHTML=heroIds.map(id=>{const p=products.find(x=>x.id===id);return p?imageMarkup(p):'';}).join('');
render(false);
